script:
(function () {
  'use strict';
  // Advanced APR: US Truth in Lending (Regulation Z, 12 CFR 1026 Appendix J) actuarial APR with an odd
  // first period and any regular payment frequency.
  //   Payments: balance B = loan amount + financed fees; regular payment P = B*i/(1-(1+i)^-n) with
  //   i = note rate / payments per year, rounded to the cent; the last payment clears the balance.
  //   Odd days = days from the loan date to one regular period before the first payment date (negative
  //   for a short first period); odd-days interest = B * note rate * odd days / 365, either added to the
  //   first payment or collected at closing as prepaid interest (a prepaid finance charge).
  //   Amount financed A = loan amount - prepaid fees - points (- prepaid interest).
  //   Unit periods to payment 1 (Appendix J (b)(5)): monthly - whole months counted back from the first
  //   payment date, leftover days / 30; quarterly, semiannual and semimonthly - 30 days per counted-back
  //   month plus leftover days, divided by 90, 180 or 15; yearly - whole years back, leftover months / 12
  //   or days / 365; weekly and biweekly - days / 7 or / 14. Payment k is t + k - 1 full periods out.
  //   A first payment on a month's last day counts back to month-ends (loan Jan 31, payment Feb 28 = 1 month).
  //   APR = i * periods per year, where i solves A = sum P_k / ((1 + f*i) * (1 + i)^t_k) (bisection).
  // Verified in Node (scratchpad tests/b2biz): regular first period, $100,000 at 6%, 120 monthly
  //   payments, $2,500 fees -> APR 6.563% (same as the standard APR formula and our APR calculator);
  //   single payment one month out -> APR = 12 * (P/A - 1) exactly; single payment 1 month + 15 days out
  //   matches the closed form A = P / ((1 + 0.5i)(1 + i)); a forward actuarial balance run at the solved
  //   rate ends at $0.00 for monthly, biweekly, semimonthly, quarterly and yearly loans with long and
  //   short first periods; no fees and no odd days -> APR equals the note rate for every frequency
  //   (weekly/biweekly: 52 and 26 periods a year, as Appendix J requires); invalid dates, first payment
  //   on or before the loan date, blank and negative input show an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var MAX_PAYMENTS = 2000;

  // --- calc ---
  var FREQ = {
    '12': { ppy: 12, kind: 'month', months: 1, label: 'Monthly' },
    '24': { ppy: 24, kind: 'semimonth', label: 'Semimonthly' },
    '26': { ppy: 26, kind: 'week', weeks: 2, label: 'Biweekly' },
    '52': { ppy: 52, kind: 'week', weeks: 1, label: 'Weekly' },
    '4': { ppy: 4, kind: 'month', months: 3, label: 'Quarterly' },
    '2': { ppy: 2, kind: 'month', months: 6, label: 'Semiannually' },
    '1': { ppy: 1, kind: 'month', months: 12, label: 'Annually' }
  };

  function parseDate(s) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s || '').trim());
    if (!m) return null;
    var y = +m[1], mo = +m[2], d = +m[3];
    if (mo < 1 || mo > 12 || d < 1 || d > daysInMonth(y, mo)) return null;
    return { y: y, m: mo, d: d };
  }
  function daysInMonth(y, m) { return new Date(Date.UTC(y, m, 0)).getUTCDate(); }
  function dayNum(dt) { return Math.round(Date.UTC(dt.y, dt.m - 1, dt.d) / 86400000); }
  function fromDayNum(n) { var x = new Date(n * 86400000); return { y: x.getUTCFullYear(), m: x.getUTCMonth() + 1, d: x.getUTCDate() }; }
  // Shift by whole months keeping the day of month (clamped to the month's last day).
  function addMonths(dt, k, day) {
    var idx = dt.y * 12 + (dt.m - 1) + k, y = Math.floor(idx / 12), m = idx - y * 12 + 1;
    return { y: y, m: m, d: Math.min(day || dt.d, daysInMonth(y, m)) };
  }

  // Full months counted back from `later` without passing `earlier`, and the leftover days.
  // A later date on the last day of its month counts back to month-ends (Jan 31 -> Feb 28 is one month).
  function anchorDay(dt) { return dt.d === daysInMonth(dt.y, dt.m) ? 31 : dt.d; }
  function monthsBack(earlier, later) {
    var e = dayNum(earlier), k = 0, day = anchorDay(later);
    while (k < 1200 && dayNum(addMonths(later, -(k + 1), day)) >= e) k++;
    return { months: k, days: dayNum(addMonths(later, -k, day)) - e };
  }

  // Appendix J (b)(5): full unit periods t and fraction f from the loan date to the first payment.
  function unitPeriods(loan, first, fq) {
    var total, size, mb;
    if (fq.kind === 'week') {
      total = dayNum(first) - dayNum(loan); size = 7 * fq.weeks;
      return { t: Math.floor(total / size), f: (total % size) / size };
    }
    mb = monthsBack(loan, first);
    if (fq.kind === 'month' && fq.months === 1) return { t: mb.months, f: mb.days / 30 };
    if (fq.kind === 'month' && fq.months === 12) {
      var years = Math.floor(mb.months / 12), leftMonths = mb.months - years * 12;
      var leftDays = dayNum(addMonths(first, -12 * years, anchorDay(first))) - dayNum(loan);
      return { t: years, f: mb.days === 0 ? leftMonths / 12 : leftDays / 365 };
    }
    total = 30 * mb.months + mb.days;
    size = fq.kind === 'semimonth' ? 15 : 30 * fq.months;
    return { t: Math.floor(total / size), f: (total % size) / size };
  }

  // Start of a regular-length first period, i.e. one period before the first payment date.
  function regularStart(first, fq) {
    if (fq.kind === 'week') return fromDayNum(dayNum(first) - 7 * fq.weeks);
    if (fq.kind === 'semimonth') return fromDayNum(dayNum(first) - 15);
    return addMonths(first, -fq.months, anchorDay(first));
  }

  function paymentDate(first, k, fq) { // k = 0 for the first payment
    if (fq.kind === 'week') return fromDayNum(dayNum(first) + 7 * fq.weeks * k);
    if (fq.kind === 'semimonth') {
      var d = addMonths(first, Math.floor(k / 2), anchorDay(first));
      return k % 2 ? fromDayNum(dayNum(d) + 15) : d;
    }
    return addMonths(first, fq.months * k, anchorDay(first));
  }

  function round2(x) { return Math.round(x * 100) / 100; }

  function schedule(balance, rate, n, fq, oddInterestInFirst) {
    var i = rate / fq.ppy;
    var pmt = i === 0 ? balance / n : balance * i / (1 - Math.pow(1 + i, -n));
    pmt = round2(pmt);
    var bal = balance, rows = [];
    for (var k = 1; k <= n; k++) {
      var interest = round2(bal * i + (k === 1 ? oddInterestInFirst : 0));
      var pay = k === n ? round2(bal + interest) : round2(pmt + (k === 1 ? oddInterestInFirst : 0));
      var principal = round2(pay - interest);
      bal = round2(bal - principal);
      rows.push({ k: k, payment: pay, interest: interest, principal: principal, balance: Math.max(0, bal) });
    }
    return { regular: pmt, rows: rows };
  }

  function pvAt(i, pays, t, f) {
    var s = 0, lead = 1 + f * i;
    for (var k = 0; k < pays.length; k++) s += pays[k] / (lead * Math.pow(1 + i, t + k));
    return s;
  }

  // Unit-period rate i with pvAt(i) = amount financed; null when it cannot be found.
  function solveRate(financed, pays, t, f) {
    var total = 0;
    pays.forEach(function (p) { total += p; });
    if (!(financed > 0) || !(total > 0)) return null;
    var lo, hi;
    if (pvAt(0, pays, t, f) >= financed) { lo = 0; hi = 1; while (pvAt(hi, pays, t, f) > financed && hi < 1e6) hi *= 2; }
    else { hi = 0; lo = -0.5; while (pvAt(lo, pays, t, f) < financed && lo > -0.999999) lo = (lo - 1) / 2; }
    if (pvAt(lo, pays, t, f) < financed || pvAt(hi, pays, t, f) > financed) return null;
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (pvAt(mid, pays, t, f) > financed) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  }

  function analyze(o) {
    // o: amount, rate (decimal), n, freq key, loan, first (dates), fees, points (%), financedFees, oddMode
    var fq = FREQ[o.freq];
    var balance = o.amount + o.financedFees;
    var oddDays = dayNum(regularStart(o.first, fq)) - dayNum(o.loan);
    var oddInterest = balance * o.rate * oddDays / 365;
    var prepaidInterest = o.oddMode === 'prepaid' ? round2(oddInterest) : 0;
    var sch = schedule(balance, o.rate, o.n, fq, o.oddMode === 'prepaid' ? 0 : oddInterest);
    var pointsCost = round2(o.amount * o.points / 100);
    var financed = o.amount - o.fees - pointsCost - prepaidInterest;
    var up = unitPeriods(o.loan, o.first, fq);
    var pays = sch.rows.map(function (r) { return r.payment; });
    var i = solveRate(financed, pays, up.t, up.f);
    var total = 0, interest = 0;
    sch.rows.forEach(function (r) { total += r.payment; interest += r.interest; });
    return {
      fq: fq, balance: balance, oddDays: oddDays, oddInterest: round2(oddInterest), prepaidInterest: prepaidInterest,
      pointsCost: pointsCost, financed: financed, unit: up, rate: i, apr: i === null ? null : i * fq.ppy,
      regular: sch.regular, first: sch.rows[0].payment, last: sch.rows[sch.rows.length - 1].payment,
      rows: sch.rows, totalPayments: round2(total), totalInterest: round2(interest),
      financeCharge: round2(total - financed), firstPeriodDays: dayNum(o.first) - dayNum(o.loan)
    };
  }
  // --- end calc ---

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function fmtDate(dt) {
    return new Date(Date.UTC(dt.y, dt.m - 1, dt.d)).toLocaleDateString('en-US', { timeZone: 'UTC', year: 'numeric', month: 'short', day: 'numeric' });
  }

  var OUT = ['aaApr', 'aaRegular', 'aaCharge', 'aaFirstPay', 'aaLastPay', 'aaFinanced', 'aaBalance', 'aaFeesOut',
             'aaOddDays', 'aaOddInterest', 'aaUnits', 'aaInterest', 'aaTotal', 'aaRateOut', 'aaSpread'];

  function clearResults() {
    OUT.forEach(function (id) { setText(id, '–'); });
    el('aaSchedule').textContent = '';
  }

  function plural(n, word) { return n + ' ' + word + (n === 1 ? '' : 's'); }

  function update() {
    var o = {
      amount: read('aaAmount'), rate: read('aaRate') / 100, n: read('aaPayments'), freq: el('aaFreq').value,
      loan: parseDate(el('aaLoanDate').value), first: parseDate(el('aaFirstDate').value),
      fees: read('aaFees', true), points: read('aaPoints', true), financedFees: read('aaAdded', true),
      oddMode: el('aaOddMode').value
    };
    var fq = FREQ[o.freq], msg = '';
    if (isNaN(o.amount) || o.amount <= 0) msg = 'Enter a loan amount greater than $0.';
    else if (isNaN(o.rate) || o.rate < 0 || o.rate > 1) msg = 'Enter an interest rate from 0% to 100%.';
    else if (isNaN(o.n) || o.n % 1 !== 0 || o.n < 1 || o.n > MAX_PAYMENTS) msg = 'Enter a whole number of payments from 1 to 2,000.';
    else if (!fq) msg = 'Choose a payment frequency.';
    else if (!o.loan || !o.first) msg = 'Enter both the loan date and the first payment date.';
    else if (dayNum(o.first) <= dayNum(o.loan)) msg = 'The first payment date must be after the loan date.';
    else if (dayNum(o.first) - dayNum(o.loan) > 2 * 366) msg = 'The first payment must be within two years of the loan date.';
    else if ([o.fees, o.points, o.financedFees].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Fees and points cannot be negative.';
    else if (o.points > 20) msg = 'Enter 20 points or fewer.';
    var r = null;
    if (!msg) {
      r = analyze(o);
      if (r.financed <= 0) msg = 'Upfront fees, points and prepaid interest must be less than the loan amount.';
      else if (r.first <= 0) msg = 'The first period is so short that the interest credit wipes out the first payment. Move the first payment date later.';
      else if (r.apr === null) msg = 'An APR can\'t be worked out for these figures. Check the amounts and dates.';
    }
    var error = el('aaError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var aprPct = r.apr * 100, ratePct = o.rate * 100;
    setText('aaApr', aprPct.toFixed(3) + '%');
    setText('aaRegular', money.format(r.regular));
    setText('aaCharge', money.format(r.financeCharge));
    setText('aaFirstPay', money.format(r.first));
    setText('aaLastPay', money.format(r.last));
    setText('aaFinanced', money.format(r.financed));
    setText('aaBalance', money.format(r.balance));
    setText('aaFeesOut', money.format(o.fees + r.pointsCost + o.financedFees + r.prepaidInterest));
    setText('aaOddDays', r.oddDays === 0 ? 'None (regular first period)' :
      (r.oddDays > 0 ? plural(r.oddDays, 'extra day') : plural(-r.oddDays, 'day') + ' short'));
    setText('aaOddInterest', (o.oddMode === 'prepaid' ? 'Prepaid at closing: ' : 'In first payment: ') +
      (r.oddInterest < 0 ? '−' : '') + money.format(Math.abs(r.oddInterest)));
    setText('aaUnits', plural(r.unit.t, 'full period') + ' + ' + (r.unit.f * 100).toFixed(1) + '% of a period');
    setText('aaInterest', money.format(r.totalInterest));
    setText('aaTotal', money.format(r.totalPayments));
    setText('aaRateOut', ratePct.toFixed(3) + '%');
    setText('aaSpread', (aprPct - ratePct >= 0 ? '+' : '−') + Math.abs(aprPct - ratePct).toFixed(3) + ' percentage points');

    var body = el('aaSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [String(row.k), fmtDate(paymentDate(o.first, row.k - 1, fq)), money.format(row.payment), money.format(row.interest),
       money.format(row.principal), money.format(row.balance)].forEach(function (text) {
        var td = document.createElement('td');
        td.textContent = text;
        tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('aaForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
